import { LocalizedString } from '@/utils/i18nHelper';

/**
 * Fichas de destino de los 10 lugares del hero.
 * Los datos duros (altitud, año UNESCO, distancias) son neutros al idioma y
 * viven una sola vez; solo se traduce el texto que de verdad cambia por idioma.
 * Cifras verificadas en fuentes oficiales (UNESCO, IGEPN, ETAPA EP, DPNG).
 */

export interface DestinationHighlight {
  title: LocalizedString;
  text: LocalizedString;
}

export interface DestinationFacts {
  /** Metros sobre el nivel del mar. */
  altitude?: string;
  /** Declaratoria UNESCO con año, si la tiene. */
  unesco?: LocalizedString;
  /** Distancia y tiempo desde Quito. */
  fromQuito?: LocalizedString;
  /** Mejor época para visitarlo. */
  bestTime: LocalizedString;
}

export interface Destination {
  slug: string;
  /** Índice del slide del hero al que corresponde, si sale en el hero. */
  heroIndex?: number;
  /** true mientras el destino no tenga una foto propia y real suya. */
  needsPhoto?: boolean;
  /** Fotos adicionales del lugar. Se muestran en una galeria bajo la portada. */
  gallery?: string[];
  region: 'galapagos' | 'andes' | 'amazonia';
  image: string;
  mobileImage?: string;
  name: LocalizedString;
  tagline: LocalizedString;
  intro: LocalizedString;
  highlights: DestinationHighlight[];
  wildlife: LocalizedString;
  /** Advertencia práctica honesta: altura, tasas, estado del volcán. */
  tip: LocalizedString;
  /** Palabras clave para emparejar los tours que van a este destino. */
  tourKeywords: string[];
  /**
   * Articulos del blog que hablan de este lugar. Se enlazan en vez de repetir
   * el contenido: asi el destino y el articulo se refuerzan en buscadores en
   * lugar de competir entre ellos.
   */
  relatedPosts?: string[];
}

/**
 * Consejos de primera mano de quien ha estado ahi. Contenido propio que no
 * existe en ninguna otra web: es lo que nos diferencia en buscadores y lo que
 * el viajero agradece. Solo algunos destinos lo tienen.
 */
const INSIDER_TIPS_DATA: Record<string, LocalizedString> = {
  'banos-pailon-del-diablo': {
    es: 'Hemos ido muchas veces al Pailón del Diablo: la caminata no es corta, pero es muy fácil y no exige forma física especial, y junto a la cascada hay una cafetería donde se puede comer. En el pueblo se alquilan buggies y coches para recorrer la zona por cuenta propia. Recomendamos el Animal Park para pasar el mediodía; los fines de semana suele haber espectáculo con caballos y conviene consultar horarios al reservar. Viniendo de Quito se pasa junto a la laguna de Yambo, en Salcedo, con vista desde el Balcón de Yambo; la laguna arrastra la leyenda de un tren hundido cuyo pito se oiría el Viernes Santo.',
    en: 'We have walked to the Pailón del Diablo many times: the trail is not short, but it is very easy and asks nothing special of your fitness, and there is a café beside the waterfall where you can eat. In town you can rent buggies and small cars and explore on your own. We recommend Animal Park for a slow midday; on weekends there is usually a horse show, and it is worth checking times when you book. Coming from Quito the road passes Yambo lagoon in Salcedo, with a view from Balcón de Yambo, and the old legend of a sunken train whose whistle is said to sound on Good Friday.',
    fr: 'Nous sommes allés bien des fois au Pailón del Diablo: la marche n’est pas courte, mais elle reste très facile et ne demande aucune condition physique particulière, et un café attend juste à côté de la cascade. Au village, on loue des buggys et des petites voitures pour explorer par soi-même. Nous recommandons Animal Park pour un midi tranquille; le week-end il y a souvent un spectacle équestre, et mieux vaut vérifier les horaires à la réservation. En venant de Quito, la route longe la lagune de Yambo, à Salcedo, avec la vue du Balcón de Yambo et la légende d’un train englouti dont le sifflet se ferait entendre le Vendredi saint.',
    de: 'Wir waren schon viele Male am Pailón del Diablo: der Weg ist nicht kurz, aber sehr einfach und verlangt keine besondere Kondition, und direkt neben dem Wasserfall gibt es ein Café, in dem man essen kann. Im Ort lassen sich Buggys und kleine Autos mieten, um die Gegend selbst zu erkunden. Wir empfehlen den Animal Park für einen ruhigen Mittag; an Wochenenden gibt es meist eine Pferdeshow, und die Zeiten sollte man bei der Buchung erfragen. Von Quito kommend führt die Straße an der Laguna de Yambo bei Salcedo vorbei, mit Blick vom Balcón de Yambo und der Legende eines versunkenen Zuges, dessen Pfeife am Karfreitag zu hören sein soll.',
    it: 'Siamo andati molte volte al Pailón del Diablo: il sentiero non è corto, ma è facilissimo e non richiede una forma fisica particolare, e accanto alla cascata c’è una caffetteria dove si può mangiare. In paese si noleggiano buggy e piccole auto per girare in autonomia. Consigliamo l’Animal Park per passare il mezzogiorno; nei fine settimana c’è spesso uno spettacolo con i cavalli, e conviene chiedere gli orari quando si prenota. Venendo da Quito la strada passa accanto alla laguna di Yambo, a Salcedo, con la vista dal Balcón de Yambo e la leggenda di un treno affondato il cui fischio si sentirebbe il Venerdì santo.',
    pt: 'Já fomos muitas vezes ao Pailón del Diablo: a caminhada não é curta, mas é muito fácil e não exige preparo físico especial, e junto à cascata há uma cafeteria onde se pode comer. No povoado alugam-se buggies e carrinhos para percorrer a região por conta própria. Recomendamos o Animal Park para passar o meio-dia; nos fins de semana costuma haver espetáculo com cavalos, e vale confirmar os horários na reserva. Vindo de Quito, a estrada passa pela laguna de Yambo, em Salcedo, com vista do Balcón de Yambo, e a laguna carrega a lenda de um trem afundado cujo apito se ouviria na Sexta-Feira Santa.',
    ja: '私たちはパイロン・デル・ディアブロへ何度も足を運んでいます。遊歩道は短くはありませんが、とても歩きやすく、特別な体力は要りません。滝のそばにはカフェがあり、食事もできます。町ではバギーや小型車を借りて、自分たちのペースで走ることもできます。昼間はアニマルパークでゆっくり過ごすのがおすすめです。週末は馬のショーが行われることが多いので、時間は予約の際にご確認ください。キトから来る道はサルセドのヤンボ湖のそばを通り、バルコン・デ・ヤンボから湖を見渡せます。沈んだ列車の汽笛が聖金曜日に聞こえるという伝説も残っています。',
    zh: '帕永魔鬼瀑布我们去过很多次。步道不算短，但非常好走，不需要特别的体力，瀑布旁边还有一家咖啡馆可以用餐。镇上可以租沙滩车和小车，自己开着四处逛逛。我们推荐把中午留给 Animal Park 这座动物园，周末常有马术表演，具体时间建议在预订时确认。从基多过来的路会经过萨尔塞多的扬博湖，Balcón de Yambo 餐厅正对着湖面；当地还流传着一列沉没火车的传说，据说受难节那天能听见它的汽笛声。',
  },
  'laguna-quilotoa': {
    es: 'En el borde del cráter ofrecen mulas y caballos para subir de vuelta. A nosotros nos incomoda verlos hacer ese ascenso una y otra vez, así que preferimos subir caminando y lo decimos con franqueza. Hay una campaña ciudadana ecuatoriana que pide regulación sobre carga, descanso y sombra para esos animales; las comunidades de Quilotoa sostienen que no hay maltrato y que ese ingreso sostiene a muchas familias. Hoy no existe una norma local que lo regule. Nuestra sugerencia es subir a pie y tomarse el tiempo; la decisión, con la información en la mano, es de cada viajero.',
    en: 'At the crater rim you will be offered mules and horses for the climb back up. It makes us uneasy to see them do that ascent over and over, so we prefer to walk up, and we say so plainly. An Ecuadorian citizens’ campaign is asking for rules on loads, rest and shade for those animals; the Quilotoa communities hold that there is no mistreatment and that the income supports many families. No local regulation covers it today. We suggest walking up and taking your time, and we leave the decision to each traveller, with the facts at hand.',
    fr: 'Au bord du cratère, on propose mules et chevaux pour remonter. Les voir refaire cette montée sans cesse nous met mal à l’aise, alors nous préférons monter à pied, et nous le disons franchement. Une campagne citoyenne équatorienne demande une réglementation sur la charge, le repos et l’ombre pour ces animaux; les communautés de Quilotoa affirment qu’il n’y a pas de maltraitance et que ces revenus font vivre bien des familles. Aucune norme locale ne l’encadre aujourd’hui. Nous suggérons de monter à pied, sans se presser, et nous laissons la décision au voyageur, informé.',
    de: 'Am Kraterrand werden Maultiere und Pferde für den Aufstieg angeboten. Uns ist unbehaglich, sie diesen Weg immer wieder gehen zu sehen, darum steigen wir lieber zu Fuß auf und sagen das offen. Eine ecuadorianische Bürgerkampagne fordert Regeln zu Last, Ruhepausen und Schatten für diese Tiere; die Gemeinden von Quilotoa halten fest, dass es keine Misshandlung gibt und diese Einnahmen viele Familien tragen. Eine lokale Vorschrift dazu gibt es heute nicht. Wir schlagen vor, zu Fuß zu gehen und sich Zeit zu lassen; entscheiden soll jeder Reisende selbst, mit den Fakten in der Hand.',
    it: 'Sul bordo del cratere offrono muli e cavalli per risalire. A noi mette a disagio vederli ripetere quella salita continuamente, così preferiamo risalire a piedi e lo diciamo con franchezza. Una campagna civica ecuadoriana chiede regole su carico, riposo e ombra per quegli animali; le comunità di Quilotoa sostengono che non ci sia maltrattamento e che quel reddito mantenga molte famiglie. Oggi non esiste una norma locale che lo regoli. Il nostro consiglio è salire a piedi con calma; la scelta, con le informazioni in mano, resta a ogni viaggiatore.',
    pt: 'Na borda da cratera oferecem mulas e cavalos para a subida de volta. A nós incomoda vê-los repetir aquela subida vezes sem conta, por isso preferimos subir a pé e dizemos isso com franqueza. Há uma campanha cidadã equatoriana que pede regulação sobre carga, descanso e sombra para esses animais; as comunidades de Quilotoa afirmam que não há maus-tratos e que essa renda sustenta muitas famílias. Hoje não existe norma local que regule o assunto. Sugerimos subir caminhando, com calma, e a decisão fica com cada viajante, com a informação à mão.',
    ja: '火口の縁では、登り返し用のラバや馬が用意されています。同じ坂を何度も往復する姿を見るのは私たちには落ち着かないもので、歩いて登るほうを選び、その理由も率直にお伝えしています。エクアドルでは、こうした動物の積載量や休息、日陰について規制を求める市民の運動があります。一方でキロトアの共同体は、虐待はなく、この収入が多くの家族を支えていると述べています。現在これを定める地域の規則はありません。私たちは時間をかけて歩くことをおすすめしますが、判断は情報を手にした旅行者ご自身に委ねます。',
    zh: '在火口湖边缘，会有人提供骡子和马匹载人爬回坡顶。看着它们一趟又一趟地重复这段上坡，我们心里并不舒服，所以自己选择步行，也会坦白地告诉旅客。厄瓜多尔有一项民间倡议，呼吁就这些动物的负重、休息和遮荫制定规范；而基洛托阿的社区则表示并不存在虐待，这份收入养着很多家庭。目前当地并没有相关法规。我们的建议是慢慢走上去，把信息摆在桌面上，最后由每位旅客自己决定。',
  },
  'galapagos-santa-cruz': {
    es: 'Galápagos restringe los plásticos de un solo uso, como sorbetes, fundas, poliestireno y botellas descartables, dentro de un programa oficial del Consejo de Gobierno. No es que esté prohibido todo el plástico, pero conviene llegar con cantimplora reutilizable. Para moverse por la isla, lo habitual y lo permitido son las bicicletas y los scooters eléctricos, no las motos de gasolina; recorrer así los alrededores en pareja es un plan precioso. Desde el aeropuerto de Baltra se cruza el Canal de Itabaca en ferry para llegar a Santa Cruz. Y se cuida mucho a la fauna: no se toca ni se alimenta a los animales, y se respeta la distancia.',
    en: 'Galápagos restricts single-use plastics such as straws, bags, polystyrene and disposable bottles, under an official programme of the Governing Council. Not all plastic is banned, but it is worth arriving with a reusable bottle. To get around the island, bicycles and electric scooters are what people use and what is allowed, not petrol motorbikes; touring the surroundings that way, two of you together, is a lovely plan. From Baltra airport you cross the Itabaca Channel by ferry to reach Santa Cruz. And the wildlife is looked after carefully: nobody touches or feeds the animals, and distance is respected.',
    fr: 'Les Galápagos limitent les plastiques à usage unique, pailles, sacs, polystyrène et bouteilles jetables, dans le cadre d’un programme officiel du Conseil de gouvernement. Tout le plastique n’est pas interdit, mais mieux vaut arriver avec une gourde réutilisable. Pour circuler sur l’île, ce sont les vélos et les scooters électriques qui se pratiquent et qui sont autorisés, pas les motos à essence; parcourir ainsi les alentours à deux est un plan magnifique. Depuis l’aéroport de Baltra, on traverse le canal d’Itabaca en ferry pour rejoindre Santa Cruz. Et la faune est très protégée: on ne touche pas, on ne nourrit pas, on garde ses distances.',
    de: 'Galápagos beschränkt Einwegplastik wie Trinkhalme, Tüten, Polystyrol und Wegwerfflaschen im Rahmen eines offiziellen Programms des Regierungsrats. Nicht jedes Plastik ist verboten, aber man sollte mit einer wiederverwendbaren Trinkflasche anreisen. Auf der Insel sind Fahrräder und Elektroscooter üblich und erlaubt, keine Benzinmotorräder; die Umgebung so zu zweit zu erkunden, ist wunderschön. Vom Flughafen Baltra setzt man mit der Fähre über den Itabaca-Kanal nach Santa Cruz über. Und die Tierwelt wird sehr geschützt: Tiere werden nicht angefasst und nicht gefüttert, und man hält Abstand.',
    it: 'Le Galápagos limitano le plastiche monouso, come cannucce, sacchetti, polistirolo e bottiglie usa e getta, dentro un programma ufficiale del Consiglio di Governo. Non è vietata tutta la plastica, ma conviene arrivare con una borraccia riutilizzabile. Per muoversi sull’isola si usano, e sono permesse, le biciclette e gli scooter elettrici, non le moto a benzina; girare così i dintorni in due è un piano bellissimo. Dall’aeroporto di Baltra si attraversa il Canale di Itabaca in traghetto per arrivare a Santa Cruz. E la fauna è molto tutelata: non si tocca, non si dà da mangiare e si rispetta la distanza.',
    pt: 'Galápagos restringe os plásticos de uso único, como palhinhas, sacolas, poliestireno e garrafas descartáveis, dentro de um programa oficial do Conselho de Governo. Não é que todo plástico esteja proibido, mas convém chegar com cantil reutilizável. Para circular pela ilha, o habitual e o permitido são as bicicletas e as scooters elétricas, não as motos a gasolina; percorrer assim os arredores a dois é um plano precioso. Do aeroporto de Baltra atravessa-se o Canal de Itabaca em ferry para chegar a Santa Cruz. E a fauna é muito cuidada: não se toca nem se alimenta os animais, e respeita-se a distância.',
    ja: 'ガラパゴスでは、ストローや袋、発泡スチロール、使い捨てボトルといった使い捨てプラスチックが、行政理事会の公式な取り組みのもとで制限されています。プラスチックのすべてが禁止というわけではありませんが、繰り返し使える水筒を持って行くとよいでしょう。島内の移動で一般的かつ認められているのは自転車と電動スクーターで、ガソリンのバイクではありません。二人でそうして周辺を回るのは、とても心地よい過ごし方です。バルトラ空港からはイタバカ海峡をフェリーで渡ってサンタクルス島へ入ります。野生動物はとても大切にされており、触らず、餌を与えず、距離を保ちます。',
    zh: '加拉帕戈斯在政府理事会的官方计划下限制一次性塑料，比如吸管、塑料袋、聚苯乙烯和一次性瓶子。并不是所有塑料都被禁止，但最好自带可重复使用的水壶。岛上出行常见且被允许的是自行车和电动滑板车，而不是汽油摩托车；两个人这样在周边兜一圈，是很美的安排。从巴尔特拉机场要乘渡船穿过伊塔巴卡海峡才能抵达圣克鲁斯岛。这里对野生动物照顾得很细致：不触摸、不投喂，并保持距离。',
  },
  'galapagos-puerto-ayora': {
    es: 'Puerto Ayora es muy tranquilo, pero al caer la tarde tiene vida propia. Hay cervecería artesanal en el pueblo, como Reptilia Galápagos Brewery, y sitios donde sale la gente que vive en la isla, como Bongo Bar y La Panga; recomendamos esos antes que cualquier lugar pensado solo para turistas. Si se sigue viaje a Isabela, el Isabela Sunset Bar tiene el mejor atardecer. Hay ferries entre islas que conectan Santa Cruz con Isabela y San Cristóbal. Y el mercado de pescado del muelle, donde pelícanos y lobos marinos esperan el descarte, pasa todos los días y es gratis.',
    en: 'Puerto Ayora is very quiet, but it comes into its own as the evening falls. There is craft beer in town, such as Reptilia Galápagos Brewery, and places where the people who live on the island go out, like Bongo Bar and La Panga; we recommend those over anywhere built only for visitors. If you travel on to Isabela, the Isabela Sunset Bar has the best sunset. Inter-island ferries connect Santa Cruz with Isabela and San Cristóbal. And the fish market on the pier, where pelicans and sea lions wait for the scraps, happens every day and costs nothing.',
    fr: 'Puerto Ayora est très calme, mais le village prend vie en fin de journée. On y trouve une brasserie artisanale, Reptilia Galápagos Brewery, et des adresses où sortent les habitants de l’île, comme le Bongo Bar et La Panga; nous les recommandons avant tout lieu pensé uniquement pour les touristes. Si le voyage continue vers Isabela, l’Isabela Sunset Bar offre le plus beau coucher de soleil. Des ferries inter-îles relient Santa Cruz à Isabela et San Cristóbal. Et le marché aux poissons du quai, où pélicans et lions de mer attendent les restes, a lieu chaque jour et ne coûte rien.',
    de: 'Puerto Ayora ist sehr ruhig, doch am Abend bekommt der Ort sein eigenes Leben. Es gibt eine Craft-Brauerei im Dorf, etwa Reptilia Galápagos Brewery, und Lokale, in denen die Inselbewohner ausgehen, wie Bongo Bar und La Panga; die empfehlen wir lieber als jeden Ort, der nur für Touristen gedacht ist. Geht die Reise weiter nach Isabela, hat die Isabela Sunset Bar den schönsten Sonnenuntergang. Fähren zwischen den Inseln verbinden Santa Cruz mit Isabela und San Cristóbal. Und der Fischmarkt am Pier, wo Pelikane und Seelöwen auf die Reste warten, findet täglich statt und kostet nichts.',
    it: 'Puerto Ayora è molto tranquillo, ma al calare della sera ha una vita sua. In paese c’è un birrificio artigianale, Reptilia Galápagos Brewery, e locali dove escono le persone che vivono sull’isola, come il Bongo Bar e La Panga; consigliamo quelli prima di qualunque posto pensato solo per i turisti. Se il viaggio prosegue verso Isabela, l’Isabela Sunset Bar ha il tramonto più bello. Ci sono traghetti tra le isole che collegano Santa Cruz con Isabela e San Cristóbal. E il mercato del pesce sul molo, dove pellicani e leoni marini attendono gli scarti, si tiene ogni giorno ed è gratuito.',
    pt: 'Puerto Ayora é muito tranquilo, mas ao cair da tarde ganha vida própria. Há cervejaria artesanal no povoado, como a Reptilia Galápagos Brewery, e lugares onde sai quem vive na ilha, como o Bongo Bar e La Panga; recomendamos esses antes de qualquer sítio pensado só para turistas. Se a viagem seguir para Isabela, o Isabela Sunset Bar tem o melhor pôr do sol. Há ferries entre ilhas que ligam Santa Cruz a Isabela e San Cristóbal. E o mercado de peixe do cais, onde pelicanos e lobos-marinhos esperam o descarte, acontece todos os dias e é de graça.',
    ja: 'プエルト・アヨラはとても静かな町ですが、夕暮れになると独特のにぎわいが生まれます。町にはレプティリア・ガラパゴス・ブルワリーのようなクラフトビールの店があり、ボンゴ・バーやラ・パンガのように島に暮らす人たちが集まる場所もあります。観光客向けだけに作られた店より、私たちはこうした場所をおすすめします。イサベラ島へ足を延ばすなら、イサベラ・サンセット・バーの夕日がいちばんです。島と島のあいだにはフェリーがあり、サンタクルスをイサベラやサンクリストバルと結んでいます。桟橋の魚市場はペリカンやアシカが残りを待つ場所で、毎日開かれ、見学は無料です。',
    zh: '阿约拉港非常安静，但一到傍晚就有自己的热闹。镇上有精酿啤酒吧，比如 Reptilia Galápagos Brewery，也有岛上居民自己会去的地方，像 Bongo Bar 和 La Panga；比起任何只为游客准备的场所，我们更推荐这些。如果继续前往伊莎贝拉岛，Isabela Sunset Bar 的日落最好看。岛际渡船把圣克鲁斯与伊莎贝拉、圣克里斯托巴尔连在一起。码头的鱼市每天都有，鹈鹕和海狮在旁边等着下水料，看热闹不用花钱。',
  },
  'quito-centro-historico': {
    es: 'El centro se recorre caminando y conviene reservarle buena parte del día. Se come muy bien: Casa Gangotena, en la plaza de San Francisco, es de lo mejor del país y pertenece a Relais & Châteaux; Vista Hermosa tiene terraza con vista, tanto en el centro histórico como en el Itchimbía; en la loma del Itchimbía están también Café Mosaico y Pim’s, con mirador sobre la ciudad; y Negroni es una buena parada de cocina italiana. Si nos dice qué le apetece comer, le reservamos la mesa.',
    en: 'The old town is walked, and it deserves a good part of the day. You eat very well here: Casa Gangotena, on Plaza de San Francisco, is among the best in the country and belongs to Relais & Châteaux; Vista Hermosa has a terrace with a view, both in the historic centre and up on Itchimbía; on the Itchimbía hill you will also find Café Mosaico and Pim’s, looking out over the city; and Negroni is a good stop for Italian cooking. Tell us what you feel like eating and we will book the table.',
    fr: 'Le centre se parcourt à pied et mérite une bonne partie de la journée. On y mange très bien: Casa Gangotena, sur la place San Francisco, est parmi les meilleures tables du pays et appartient à Relais & Châteaux; Vista Hermosa a une terrasse avec vue, dans le centre historique comme sur l’Itchimbía; sur la colline de l’Itchimbía se trouvent aussi Café Mosaico et Pim’s, en belvédère sur la ville; et Negroni est une bonne halte de cuisine italienne. Dites-nous ce qui vous ferait envie et nous réservons la table.',
    de: 'Die Altstadt erkundet man zu Fuß, und sie verdient einen guten Teil des Tages. Man isst hier sehr gut: Casa Gangotena an der Plaza de San Francisco gehört zum Besten des Landes und ist Teil von Relais & Châteaux; Vista Hermosa hat eine Terrasse mit Aussicht, sowohl in der Altstadt als auch am Itchimbía; auf dem Hügel Itchimbía liegen außerdem Café Mosaico und Pim’s mit Blick über die Stadt; und Negroni ist ein guter Halt für italienische Küche. Sagen Sie uns, worauf Sie Lust haben, und wir reservieren den Tisch.',
    it: 'Il centro si percorre a piedi e merita buona parte della giornata. Si mangia molto bene: Casa Gangotena, sulla plaza de San Francisco, è tra le migliori del paese e appartiene a Relais & Châteaux; Vista Hermosa ha una terrazza con vista, sia nel centro storico sia all’Itchimbía; sulla collina dell’Itchimbía ci sono anche Café Mosaico e Pim’s, affacciati sulla città; e Negroni è una buona sosta di cucina italiana. Se ci dice cosa le va di mangiare, le prenotiamo il tavolo.',
    pt: 'O centro percorre-se a pé e convém reservar-lhe boa parte do dia. Come-se muito bem: a Casa Gangotena, na praça de San Francisco, é das melhores do país e pertence à Relais & Châteaux; o Vista Hermosa tem esplanada com vista, tanto no centro histórico como no Itchimbía; na colina do Itchimbía estão também o Café Mosaico e o Pim’s, com mirante sobre a cidade; e o Negroni é uma boa parada de cozinha italiana. Se nos disser o que lhe apetece comer, reservamos a mesa.',
    ja: '旧市街は歩いて回る場所で、一日のかなりの時間をあてる価値があります。食事もとてもよく、サンフランシスコ広場のカサ・ガンゴテナはエクアドルでも指折りの一軒で、ルレ・エ・シャトーに加盟しています。ビスタ・エルモサは旧市街とイチンビアの両方に眺めのよいテラスを持ち、イチンビアの丘にはカフェ・モサイコやピムズもあって、街を見下ろせます。イタリア料理ならネグローニがよい一軒です。何を食べたいか教えていただければ、私たちがテーブルをお取りします。',
    zh: '老城区适合步行，值得留出一天中相当长的时间。这里吃得很好：圣弗朗西斯科广场旁的 Casa Gangotena 是全国最出色的餐厅之一，属于罗莱夏朵；Vista Hermosa 在老城和伊钦比亚都有带景观的露台；伊钦比亚山丘上还有 Café Mosaico 和 Pim’s，可以俯瞰整座城市；想吃意餐，Negroni 是不错的一站。只要告诉我们您想吃什么，我们替您订好位子。',
  },
  'otavalo': {
    es: 'El tour de Otavalo es mucho más que el mercado: la gracia está en las lagunas. En la laguna de Cuicocha, una caldera con dos islotes, se puede dar el paseo en lancha entre ellos. En el lago San Pablo, al pie del Imbabura, hay marina y paseo en bote, y hay quien nada en aguas abiertas. La Plaza de Ponchos abre todos los días, pero el sábado es el día grande y el miércoles el segundo. Conocer Imbabura con calma es un lujo.',
    en: 'The Otavalo tour is much more than the market: the lakes are where the charm is. At Cuicocha, a caldera with two islets, you can take the boat ride between them. On Lake San Pablo, at the foot of Imbabura, there is a marina and a boat outing, and some people swim in open water. The Plaza de Ponchos is open every day, but Saturday is the big day and Wednesday the second. Getting to know Imbabura slowly is a luxury.',
    fr: 'Le tour d’Otavalo est bien plus que le marché: tout le charme est dans les lagunes. À Cuicocha, une caldeira avec deux îlots, on peut faire la promenade en barque entre les deux. Sur le lac San Pablo, au pied de l’Imbabura, il y a une marina et une sortie en bateau, et certains nagent en eau libre. La Plaza de Ponchos ouvre tous les jours, mais le samedi est le grand jour et le mercredi le deuxième. Découvrir l’Imbabura sans se presser est un luxe.',
    de: 'Die Otavalo-Tour ist viel mehr als der Markt: der Reiz liegt in den Seen. An der Laguna Cuicocha, einer Caldera mit zwei Inselchen, kann man die Bootsfahrt zwischen ihnen machen. Am Lago San Pablo, am Fuß des Imbabura, gibt es einen Yachthafen und eine Bootsfahrt, und manche schwimmen im offenen Wasser. Die Plaza de Ponchos ist täglich geöffnet, doch Samstag ist der große Tag und Mittwoch der zweite. Imbabura in Ruhe kennenzulernen, ist ein Luxus.',
    it: 'Il tour di Otavalo è molto più del mercato: il bello sta nelle lagune. Alla laguna di Cuicocha, una caldera con due isolotti, si può fare il giro in barca tra i due. Sul lago San Pablo, ai piedi dell’Imbabura, c’è una marina e un’uscita in barca, e c’è chi nuota in acque aperte. La Plaza de Ponchos è aperta tutti i giorni, ma il sabato è il giorno grande e il mercoledì il secondo. Conoscere l’Imbabura con calma è un lusso.',
    pt: 'O tour de Otavalo é muito mais do que o mercado: a graça está nas lagunas. Na laguna de Cuicocha, uma caldeira com dois ilhéus, pode-se fazer o passeio de barco entre eles. No lago San Pablo, ao pé do Imbabura, há marina e passeio de barco, e há quem nade em águas abertas. A Plaza de Ponchos abre todos os dias, mas o sábado é o dia grande e a quarta-feira o segundo. Conhecer o Imbabura com calma é um luxo.',
    ja: 'オタバロは市場だけの場所ではありません。いちばんの魅力は湖にあります。二つの小島を抱くカルデラ湖クイコチャでは、島のあいだをボートで巡ることができます。インババラ山のふもとのサンパブロ湖にはマリーナがあり、ボートに乗って過ごせますし、オープンウォーターを泳ぐ人もいます。ポンチョ広場の市は毎日開かれていますが、いちばん賑わうのは土曜日で、次が水曜日です。インババラをゆっくり知っていくのは、ぜいたくな時間です。',
    zh: '奥塔瓦洛之行远不只是市场，真正的魅力在几处湖泊。库伊科查是一座火口湖，湖中有两座小岛，可以坐船在岛之间游览。圣巴勃罗湖位于因巴布拉山脚下，有码头，可以乘船，也有人在开放水域游泳。斗篷广场每天都开，但周六是最热闹的一天，周三次之。慢慢认识因巴布拉，本身就是一种奢侈。',
  },
  'cuenca-cajas': {
    es: 'Recomendamos los baños de cajón, una tradición medicinal andina muy cuencana: un baño de vapor individual en una caja de madera de la que solo sale la cabeza. Se hacen en la parroquia Baños de Cuenca, la zona termal de la ciudad, donde están Piedra de Agua, Novaqua y la Hostería Durán; conviene confirmar al reservar cuál ofrece el cajón y en qué horario. El Cajas, con sus lagunas y sus bosques de Polylepis, es de los paisajes más fotogénicos del país, y la luz cambia en minutos: quien vaya con cámara debe ir preparado.',
    en: 'We recommend the baños de cajón, a very Cuenca Andean healing tradition: a steam bath for one inside a wooden box, with only your head outside. They are found in the parish of Baños de Cuenca, the city’s thermal area, home to Piedra de Agua, Novaqua and Hostería Durán; it is best to confirm when booking which one offers the cajón and at what times. El Cajas, with its lakes and Polylepis woods, is among the most photogenic landscapes in the country, and the light changes within minutes: come prepared if you bring a camera.',
    fr: 'Nous recommandons les baños de cajón, une tradition médicinale andine très cuencaine: un bain de vapeur individuel dans une caisse de bois dont seule la tête sort. On les trouve dans la paroisse de Baños de Cuenca, la zone thermale de la ville, où se trouvent Piedra de Agua, Novaqua et l’Hostería Durán; mieux vaut confirmer à la réservation lequel propose le cajón et à quels horaires. El Cajas, avec ses lagunes et ses bois de Polylepis, est l’un des paysages les plus photogéniques du pays, et la lumière change en quelques minutes: qui vient avec un appareil doit être prêt.',
    de: 'Wir empfehlen die baños de cajón, eine sehr für Cuenca typische andine Heiltradition: ein Dampfbad für eine Person in einem Holzkasten, aus dem nur der Kopf herausschaut. Angeboten werden sie in der Gemeinde Baños de Cuenca, dem Thermalviertel der Stadt, wo Piedra de Agua, Novaqua und die Hostería Durán liegen; bei der Buchung sollte man klären, wer den cajón anbietet und zu welchen Zeiten. El Cajas mit seinen Seen und Polylepis-Wäldern gehört zu den fotogensten Landschaften des Landes, und das Licht wechselt in Minuten: wer eine Kamera mitnimmt, sollte vorbereitet sein.',
    it: 'Consigliamo i baños de cajón, una tradizione medicinale andina molto di Cuenca: un bagno di vapore individuale in una cassa di legno da cui esce solo la testa. Si trovano nella parrocchia Baños de Cuenca, la zona termale della città, dove ci sono Piedra de Agua, Novaqua e l’Hostería Durán; conviene confermare in fase di prenotazione chi offre il cajón e con quali orari. El Cajas, con le sue lagune e i boschi di Polylepis, è tra i paesaggi più fotogenici del paese, e la luce cambia in pochi minuti: chi porta la macchina fotografica deve arrivare preparato.',
    pt: 'Recomendamos os baños de cajón, uma tradição medicinal andina muito de Cuenca: um banho de vapor individual numa caixa de madeira de onde só sai a cabeça. Fazem-se na paróquia Baños de Cuenca, a zona termal da cidade, onde estão a Piedra de Agua, a Novaqua e a Hostería Durán; convém confirmar na reserva qual oferece o cajón e em que horário. El Cajas, com as suas lagunas e os bosques de Polylepis, é das paisagens mais fotogénicas do país, e a luz muda em minutos: quem levar câmara deve ir preparado.',
    ja: 'おすすめしたいのがバーニョス・デ・カホン、クエンカらしいアンデスの療養の伝統です。木の箱に一人で入り、頭だけを外に出して蒸気を浴びます。市内の温泉地区であるバーニョス・デ・クエンカ教区で受けられ、ピエドラ・デ・アグア、ノバクア、オステリア・ドゥランなどがあります。どこでカホンを用意しているか、どの時間に受けられるかは、予約の際にご確認ください。エル・カハスは湖とポリレピスの林が広がる、国内でもとりわけ絵になる風景で、光は数分で変わります。カメラを持って行く方は備えを万全に。',
    zh: '我们很推荐 baños de cajón，这是昆卡一带很有代表性的安第斯疗养传统：一个人坐进木箱里蒸汽浴，只把头露在外面。它们集中在城里的温泉区——巴尼奥斯·德·昆卡堂区，那里有 Piedra de Agua、Novaqua 和 Hostería Durán；哪一家提供木箱浴、在什么时间，建议在预订时确认。埃尔卡哈斯有高山湖泊和 Polylepis 林，是全国最上镜的风景之一，光线几分钟就会变，带相机的人最好做足准备。',
  },
  'papallacta': { es: 'El frío de la subida hace que el agua caliente se disfrute el doble, y la carretera hasta allá es de las más bonitas del país, cruzando el páramo. Recomendamos quedarse a comer: caldo de gallina, quesito con choclo y sobre todo la trucha, que aquí es de criadero andino. La trucha arcoíris comparte género con los salmones del Pacífico, así que lo de llamarla prima hermana del salmón se sostiene, y es buena fuente de proteína y de omega-3. Es el destino que recomendamos a quien busca un día de descanso y cuerpo, no de esfuerzo.', en: 'The cold of the climb makes the hot water twice as good, and the road up there is one of the prettiest in the country, crossing the páramo. We recommend staying for lunch: caldo de gallina, fresh cheese with corn and above all the trout, which here comes from Andean farms. Rainbow trout shares a genus with Pacific salmon, so calling it the salmon’s first cousin holds up, and it is a good source of protein and omega-3. This is the destination we recommend to anyone after a day of rest for the body, not effort.', fr: 'Le froid de la montée fait qu’on savoure deux fois plus l’eau chaude, et la route qui y mène est l’une des plus belles du pays, en pleine traversée du páramo. Nous conseillons de rester déjeuner : caldo de gallina, fromage frais avec du maïs et surtout la truite, ici d’élevage andin. La truite arc-en-ciel partage son genre avec les saumons du Pacifique : l’appeler cousine germaine du saumon se défend, et c’est une bonne source de protéines et d’oméga-3. C’est la destination que nous conseillons à qui cherche une journée de repos pour le corps, pas d’effort.', de: 'Die Kälte des Aufstiegs lässt das heiße Wasser doppelt gut wirken, und die Straße dorthin ist eine der schönsten des Landes, mitten durch den Páramo. Wir empfehlen, zum Essen zu bleiben: caldo de gallina, frischer Käse mit Mais und vor allem die Forelle, hier aus andiner Aufzucht. Die Regenbogenforelle gehört zur selben Gattung wie die Pazifiklachse, die Rede von der Cousine des Lachses hält also stand, und sie liefert gut Protein und Omega-3. Das ist unser Ziel für alle, die einen Tag Ruhe für den Körper suchen, keine Anstrengung.', it: 'Il freddo della salita fa godere il doppio l’acqua calda, e la strada per arrivarci è tra le più belle del paese, tutta in mezzo al páramo. Consigliamo di fermarsi a mangiare: caldo de gallina, formaggio fresco con mais e soprattutto la trota, qui d’allevamento andino. La trota iridea condivide il genere con i salmoni del Pacifico, quindi chiamarla cugina di primo grado del salmone regge, ed è una buona fonte di proteine e omega-3. È la meta che consigliamo a chi cerca una giornata di riposo per il corpo, non di fatica.', pt: 'O frio da subida faz com que a água quente se aproveite a dobrar, e a estrada até lá é das mais bonitas do país, a atravessar o páramo. Recomendamos ficar para comer: caldo de galinha, queijo fresco com milho e sobretudo a truta, que aqui é de criação andina. A truta-arco-íris partilha o género com os salmões do Pacífico, por isso chamar-lhe prima do salmão sustenta-se, e é boa fonte de proteína e de ómega-3. É o destino que recomendamos a quem procura um dia de descanso e de corpo, não de esforço.', ja: '登りの寒さのおかげで、熱い湯のありがたさが二倍になります。そこまでの道もパラモを横切る国内随一の美しさです。食事をしていくことをおすすめします。カルド・デ・ガジーナ、チーズとトウモロコシ、そして何よりマス。ここのマスはアンデスの養殖です。ニジマスは太平洋のサケと同じ属なので、サケのいとこと呼ぶのは筋が通っていますし、たんぱく質とオメガ3もよくとれます。体を休める一日を求める方に、私たちがすすめる行き先です。', zh: '一路上山的寒冷，让热水的舒服加倍；通往那里的公路穿过帕拉莫高原，是我们心里全国最美的路之一。我们建议留下来吃一顿：鸡汤、鲜奶酪配玉米，尤其是鳟鱼，这里的鳟鱼来自安第斯的养殖场。虹鳟与太平洋的鲑鱼同属，说它是鲑鱼的表亲站得住脚，而且蛋白质和欧米伽3都很充足。如果想要的是让身体休息的一天，而不是体力挑战，这就是我们会推荐的地方。' },
  'mindo': { es: 'Es de nuestros sitios favoritos y da para un día entero o para quedarse. Se baja desde el páramo de la sierra hasta el bosque nublado y el cambio de paisaje es brutal. Hay mucho que hacer: bajar por las cascadas, la tarabita, cuadrones y el mariposario, que nos parece precioso y gusta a todas las edades. Se come muy bien. Un matiz sobre el páramo que se cruza al venir: no es exclusivo de Ecuador y Colombia, como suele decirse. Se extiende desde Venezuela hasta el norte de Perú, con enclaves en Costa Rica y Panamá, aunque Ecuador y Colombia concentran la mayor parte y los mejores accesos.', en: 'One of our favourite places, good for a full day or for a longer stay. You drop from the highland páramo into cloud forest and the change of scenery is startling. There is plenty to do: canyoning down the waterfalls, the cable car, quad bikes and the butterfly farm, which we find lovely and which pleases all ages. The food is good. One nuance about the páramo you cross on the way: it is not exclusive to Ecuador and Colombia, as is often said. It runs from Venezuela to northern Peru, with pockets in Costa Rica and Panama, though Ecuador and Colombia hold most of it and the best access.', fr: 'C’est l’un de nos endroits préférés, bon pour une journée entière comme pour un séjour plus long. On descend du páramo d’altitude vers la forêt de nuages et le changement de paysage est saisissant. Il y a beaucoup à faire : descendre les cascades, la tarabita, les quads et la ferme aux papillons, que nous trouvons magnifique et qui plaît à tous les âges. On y mange très bien. Une nuance sur le páramo que l’on traverse en venant : il n’est pas propre à l’Équateur et à la Colombie, comme on le dit souvent. Il s’étend du Venezuela au nord du Pérou, avec des enclaves au Costa Rica et au Panama, même si l’Équateur et la Colombie en concentrent l’essentiel et les meilleurs accès.', de: 'Einer unserer Lieblingsorte, gut für einen ganzen Tag oder für einen längeren Aufenthalt. Man steigt vom Hochland-Páramo in den Nebelwald hinab, und der Landschaftswechsel ist verblüffend. Es gibt viel zu tun: die Wasserfälle abseilen, die Seilbahn, Quads und die Schmetterlingsfarm, die wir wunderschön finden und die jedem Alter gefällt. Gegessen wird hier gut. Eine Nuance zum Páramo, den man auf dem Weg überquert: Er ist nicht exklusiv ecuadorianisch und kolumbianisch, wie oft behauptet. Er reicht von Venezuela bis in den Norden Perus, mit Enklaven in Costa Rica und Panama, auch wenn Ecuador und Kolumbien den größten Teil und die besten Zugänge haben.', it: 'È uno dei nostri posti preferiti, buono per una giornata intera o per restare più a lungo. Si scende dal páramo d’altura alla foresta nuvolosa e il cambio di paesaggio è impressionante. C’è molto da fare: scendere le cascate, la teleferica, i quad e la casa delle farfalle, che ci sembra bellissima e piace a tutte le età. Si mangia molto bene. Una sfumatura sul páramo che si attraversa arrivando: non è esclusivo di Ecuador e Colombia, come si dice spesso. Si estende dal Venezuela al nord del Perù, con enclavi in Costa Rica e Panama, anche se Ecuador e Colombia ne concentrano la maggior parte e i migliori accessi.', pt: 'É um dos nossos sítios favoritos, bom para um dia inteiro ou para ficar mais tempo. Desce-se do páramo da serra para a floresta nublada e a mudança de paisagem é impressionante. Há muito que fazer: descer as cascatas, o teleférico, os quads e o borboletário, que nos parece lindíssimo e agrada a todas as idades. Come-se muito bem. Uma nuance sobre o páramo que se atravessa ao vir: não é exclusivo do Equador e da Colômbia, como se costuma dizer. Estende-se da Venezuela ao norte do Peru, com enclaves na Costa Rica e no Panamá, embora o Equador e a Colômbia concentrem a maior parte e os melhores acessos.', ja: '私たちのお気に入りのひとつで、日帰りでも泊まりでも楽しめます。高地のパラモから雲霧林へ下るので、景色の変わり方がとても劇的です。やれることは多く、滝の下降、タラビタ、四輪バギー、そして私たちがとても美しいと思う蝶園は、どの年代の方にも喜ばれます。食事もおいしいところです。来る途中に越えるパラモについて一点だけ。よく言われるようにエクアドルとコロンビアだけのものではなく、ベネズエラからペルー北部まで広がり、コスタリカやパナマにも点在します。とはいえ大半はエクアドルとコロンビアにあり、アクセスもここが一番です。', zh: '这是我们最喜欢的地方之一，待一整天可以，住下来也合适。从高地帕拉莫一路降到云雾林，景观的变化非常强烈。可做的事很多：溯降瀑布、坐缆车、开四轮越野车，还有蝴蝶园，我们觉得它很美，各个年龄都会喜欢。这里也很好吃。关于来时穿过的帕拉莫，有一点要说清楚：它并不像常说的那样只属于厄瓜多尔和哥伦比亚，而是从委内瑞拉延伸到秘鲁北部，在哥斯达黎加和巴拿马也有零星分布；不过大部分确实集中在厄瓜多尔和哥伦比亚，最好的入口也在这里。' },
  'galapagos-isabela': { es: 'Es nuestra isla preferida: la más grande y con muy poca gente. Todo el camino al Muro de las Lágrimas es un encadenado de sitios preciosos y se hace caminando o en bicicleta, parando en pozas, playas y miradores; el Mirador Cerro Orchilla es de los que más nos gustan. Hay vida nocturna, pero muy tranquila y sobre todo de visitantes, poca gente de la isla. Se llega en lancha desde Santa Cruz o San Cristóbal. En la parte alta algunas fincas reciben visitantes y ofrecen fruta de temporada; conviene confirmarlo al reservar, porque depende de la finca y de la época.', en: 'Isabela is our favourite island: the largest, and with very few people on it. The whole walk to the Wall of Tears is a string of beautiful spots, done on foot or by bike, stopping at lagoons, beaches and viewpoints; the Cerro Orchilla lookout is one we like most. There is nightlife, but very quiet and mostly among visitors, with few islanders out. You get there by boat from Santa Cruz or San Cristóbal. Up in the highlands some farms receive visitors and offer seasonal fruit; worth confirming when you book, since it depends on the farm and the season.', fr: 'Isabela est notre île préférée : la plus grande, et avec très peu de monde. Tout le chemin du Mur des Larmes est un enchaînement de très beaux endroits, à pied ou à vélo, avec des arrêts aux mares, aux plages et aux miradors ; celui du Cerro Orchilla est l’un de nos préférés. Il y a une vie nocturne, mais très calme et surtout entre visiteurs, peu d’insulaires. On y arrive en bateau depuis Santa Cruz ou San Cristóbal. Sur les hauteurs, certaines fermes reçoivent des visiteurs et proposent des fruits de saison ; mieux vaut le confirmer à la réservation, cela dépend de la ferme et de la saison.', de: 'Isabela ist unsere Lieblingsinsel: die größte, und mit sehr wenigen Menschen. Der ganze Weg zur Mauer der Tränen ist eine Kette schöner Orte, zu Fuß oder mit dem Rad, mit Stopps an Lagunen, Stränden und Aussichtspunkten; der Mirador Cerro Orchilla gehört zu unseren liebsten. Es gibt ein Nachtleben, aber sehr ruhig und vor allem unter Besuchern, wenige Inselbewohner. Man kommt per Boot von Santa Cruz oder San Cristóbal. Im Hochland empfangen einige Farmen Besucher und bieten Früchte der Saison; am besten bei der Buchung bestätigen, denn es hängt von der Farm und der Jahreszeit ab.', it: 'Isabela è la nostra isola preferita: la più grande e con pochissima gente. Tutto il cammino al Muro delle Lacrime è un susseguirsi di posti bellissimi, a piedi o in bicicletta, con sosta in pozze, spiagge e punti panoramici; il mirador Cerro Orchilla è tra quelli che ci piacciono di più. C’è vita notturna, ma molto tranquilla e soprattutto fra visitatori, pochi isolani. Si arriva in barca da Santa Cruz o San Cristóbal. Nella parte alta alcune fattorie ricevono visitatori e offrono frutta di stagione; meglio confermarlo in fase di prenotazione, dipende dalla fattoria e dal periodo.', pt: 'Isabela é a nossa ilha preferida: a maior e com muito pouca gente. Todo o caminho para o Muro das Lágrimas é um encadeado de sítios lindos, a pé ou de bicicleta, com paradas em poças, praias e miradouros; o Mirador Cerro Orchilla é dos que mais gostamos. Há vida noturna, mas muito tranquila e sobretudo de visitantes, pouca gente da ilha. Chega-se de barco desde Santa Cruz ou San Cristóbal. Na parte alta algumas fazendas recebem visitantes e oferecem fruta da época; convém confirmar na reserva, porque depende da fazenda e da estação.', ja: 'イサベラは私たちの一番好きな島です。最大の島なのに、人はごくわずか。涙の壁までの道は美しい場所の連続で、歩きでも自転車でも、潟や浜辺、展望台に立ち寄りながら進めます。セロ・オルチジャ展望台はとくに気に入っている場所です。夜の店もありますが、とても静かで、客層はほとんど旅行者で、島の人は少なめです。行き方はサンタ・クルスかサン・クリストバルからの船。高地では訪問者を受け入れて季節の果物を出す農園もありますが、農園や時期によるので予約時に確認するのがよいでしょう。', zh: '伊莎贝拉是我们最喜欢的岛：面积最大，人却很少。通往泪墙的整条路是一串美丽的地点，步行或骑车都行，沿途在潟湖、海滩和观景台停留，其中塞罗奥奇利亚观景台是我们最喜欢的几处之一。岛上有夜生活，但很安静，而且多是游客，本地人不多。前往要从圣克鲁斯或圣克里斯托瓦尔坐船。高地上有些农场接待来访者，会提供当季水果；建议预订时确认，因为要看具体农场和季节。' },
};

