        title: { es: 'San Francisco', en: 'San Francisco', fr: 'San Francisco', de: 'San Francisco', it: 'San Francisco', pt: 'San Francisco', ja: 'サン・フランシスコ教会', zh: '圣弗朗西斯科教堂' },
        text: { es: 'El mayor conjunto arquitectónico colonial de América: 3,5 hectáreas y trece claustros.', en: 'The largest colonial architectural complex in the Americas: 3.5 hectares and thirteen cloisters.', fr: 'Le plus grand ensemble architectural colonial des Amériques : 3,5 hectares et treize cloîtres.', de: 'Der größte koloniale Gebäudekomplex Amerikas: 3,5 Hektar und dreizehn Kreuzgänge.', it: 'Il più grande complesso architettonico coloniale delle Americhe: 3,5 ettari e tredici chiostri.', pt: 'O maior conjunto arquitetônico colonial das Américas: 3,5 hectares e treze claustros.', ja: 'アメリカ大陸最大の植民地建築群。3.5ヘクタールに13の回廊。', zh: '美洲最大的殖民建筑群：3.5公顷，十三座回廊。' },
